-- 485_hidden_curated.sql — #485 Katy-Energy Corridor part 1: curated rows for 22 HIDDEN storyless OSM pins
-- (handoff §6 story-lines (y)). seed-resolve.ts cannot see a hidden pin, so a story line would plant a second pin beside it;
-- a curated row under the pin's EXACT name at its stored coordinate brings the pin back with its story instead.
-- Checks done (2026-10-28, warm tiles only): each pin's name, id and coordinate as stored in places:v34 rows 593_-1917,
-- 593_-1918, 594_-1918, 596_-1913, 596_-1917, 597_-1913 (first read) and 596_-1914, 595_-1912 (second read, after pre-warm round 3);
-- each absent from its tile's served answer (0, 0, 0, 19, 7, 4, 7 and 17 pins, all under the ~20 cap), so hidden (FROM
-- MIDDLESEX-UNION (3)). Most are OSM nodes 124036xxxxx — the area's Texas Historical
-- Commission markers mapped one by one in OSM — plus the Katy Heritage Park buildings (ways 6274688xx, 627582535/538).
-- Stories are worded from each marker's own text (HMdb, cited per row). Pittsville's pin sits in tile 595_-1919, just outside
-- the box, but is stored and served through 594_-1918. Not given rows (no marker text): Johnny Nelson Katy Heritage Museum,
-- Tri-County Marker; Albert and Ethel Herzstein (a biography, place unclear).
-- Moore Log House (osm_node12403587932) is CORE Houston's ground (tile column -1911) but stored in 595_-1912's row; the curated row
-- matches by name and coordinate, so territory does not matter — one more hidden pin back.
-- Downtown Katy's other markers (Dube's, the caboose, the depot, the schoolhouse, three houses) are NOT OSM pins — they stay story
-- lines. STILL OWED: tile 595_-1913 (Wheaton's Ford, Gray Lodge, Tagore) was cold at both reads.
--
-- RUN: the SQL editor, this whole file in its own tab. Re-runnable: skipped when a same-name curated row sits within 50 m.
-- Expect 22 rows returned on the first run, 0 on a re-run.
-- THEN (new tab): select name, category, dist_m from public.curated_category_backfill(true) order by 1;
--   expect these 22 names among the rows, dist_m 0.
-- BACK-OUT: delete from public.curated_descriptions where note = '#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)';

with v(name, lat, lng, description, source_url, note) as (values
  ($t$Humble Mess Hall$t$, 29.7913133::double precision, -95.8256463::double precision, $t$This hall served Humble Oil's recycling plant west of town, opened in 1943 on the Katy Gas Field, which the marker credits with supplying the aviation fuel used by the Allied forces in the Second World War.$t$, $t$https://www.hmdb.org/m.asp?m=165301$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$The Wright House$t$, 29.7912841::double precision, -95.8258244::double precision, $t$Pharmacist David Wright bought this 1898 house in 1899, and in 1906 he ran Katy's first telephone line from it.$t$, $t$https://www.hmdb.org/m.asp?m=165303$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Old Katy Post Office$t$, 29.7910677::double precision, -95.8263264::double precision, $t$Built before 1920, this little building became Katy's fourth post office in 1922, then served as a grocery, a warehouse, a jewelry store and a home before it was moved here in 2003.$t$, $t$https://www.hmdb.org/m.asp?m=165308$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$The Featherston House$t$, 29.7913733::double precision, -95.8261194::double precision, $t$Built in 1898 for the family of W.H. Featherston and later moved here from Second Street, this house belonged to the man who became the first pastor of Katy's Baptist church in 1906.$t$, $t$https://www.hmdb.org/m.asp?m=165305$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$The Stockdick House$t$, 29.7914085::double precision, -95.8263047::double precision, $t$Built in 1916 for Adam Henry Stockdick, Katy's first real estate agent, this house first stood at Fourth Street and Avenue A; his son William Chester bought it in 1929.$t$, $t$https://www.hmdb.org/m.asp?m=165306$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Katy Heritage Park$t$, 29.7914246::double precision, -95.8256981::double precision, $t$The Katy Heritage Society, founded in 1979, gathered three old houses and the old post office, and in 2002 joined the city to make this park.$t$, $t$https://www.hmdb.org/m.asp?m=165298$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$The City of Katy$t$, 29.78742::double precision, -95.82238::double precision, $t$Karankawa hunters chased buffalo here into the 1820s, Fifth Street still follows the San Felipe Road Santa Anna marched in 1836, and the stagecoach stop called Cane Island became the town of Katy after the "Katy" railroad arrived in 1895.$t$, $t$https://www.hmdb.org/m.asp?m=211564$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$First United Methodist Church of Katy$t$, 29.78982::double precision, -95.82119::double precision, $t$In 1898 Baptists, Disciples of Christ, Presbyterians, Quakers and Methodists shared one union Sunday school in Willard James's home; around 1900 the Methodists formed their own congregation, which became this church.$t$, $t$https://www.hmdb.org/m.asp?m=157820$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$First Baptist Church of Katy$t$, 29.78347::double precision, -95.81964::double precision, $t$On November 20, 1898, the Rev. T.L. Scruggs led the first meeting of what became Katy's First Baptist Church; W.H. Featherston was among its twelve charter members.$t$, $t$https://www.hmdb.org/m.asp?m=157825$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Bear Creek Methodist Church and Cemetery$t$, 29.8143::double precision, -95.64518::double precision, $t$German settlers founded the Bear Creek German Methodist Church in 1879 and moved its sanctuary here in 1902; floods led to the Addicks Reservoir in 1940 and the church moved away, but the cemetery, first used in 1904, is still active.$t$, $t$https://www.hmdb.org/m.asp?m=73450$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Town of Fulshear$t$, 29.68884::double precision, -95.90073::double precision, $t$Churchill Fulshear, one of Austin's "Old 300," got this land in 1824; his son, a veteran of the Texas Revolution, bred and raced horses at Churchill Downs in Pittsville two miles north, and his pupil John Huggins went on to train the first American horse to win the English Derby.$t$, $t$https://www.hmdb.org/m.asp?m=145864$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Fulshear Cemetery$t$, 29.7001::double precision, -95.90799::double precision, $t$Churchill Fulshear Jr. gave more than six acres of his father's 1824 grant to the Methodist church in 1851, and this burial ground began as Union Chappel Cemetery.$t$, $t$https://www.hmdb.org/m.asp?m=145862$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Fulshear Black Cemetery$t$, 29.6884::double precision, -95.90456::double precision, $t$Oral tradition holds that this began as the slave cemetery of Churchill Fulshear's plantation; many early graves are unmarked, and the oldest headstone is Rebecca Scott's, from 1915.$t$, $t$https://www.hmdb.org/m.asp?m=157667$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$First United Methodist Church Fulshear$t$, 29.69245::double precision, -95.90161::double precision, $t$Circuit rider John Patton founded Union Chappel Methodist Church in 1844 at a meeting ground on Churchill Fulshear Jr.'s land, which he deeded to the church in 1851.$t$, $t$https://www.hmdb.org/m.asp?m=225292$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Pleasant Hill Cemetery$t$, 29.65586::double precision, -95.88237::double precision, $t$In 1910 two acres here went to the Pleasant Hill Missionary Baptist Church, and from about 1930 the ground behind the sanctuary became a cemetery, known for its many handmade concrete grave markers.$t$, $t$https://www.hmdb.org/m.asp?m=157672$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Randon & Pennington Grant of 1824$t$, 29.64074::double precision, -95.88239::double precision, $t$In 1824 David Randon, an Alabaman of part Creek descent, and his partner Isaac Pennington were granted 4,428 acres on the Brazos between the Foster and Fulshear leagues; Randon bought out Pennington and became one of the most successful planters in Austin's colony.$t$, $t$https://www.hmdb.org/m.asp?m=209258$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$John Foster Land Grant$t$, 29.6534::double precision, -95.84402::double precision, $t$John Foster, one of Austin's "Old Three Hundred," came to Texas in 1822 and received about 12,000 acres from Mexico; after his death the land was split among his ten children, and the community that grew here took the name Foster.$t$, $t$https://www.hmdb.org/m.asp?m=157733$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Pittsville$t$, 29.72796::double precision, -95.92824::double precision, $t$Planters who preferred the open prairie to the flood-prone Brazos bottoms settled Pittsville in the 1840s and named it for storekeepers A.R. and Amanda Pitts; it was a busy trade center by 1860, and Churchill Fulshear Jr. raced horses at his Churchill Downs here.$t$, $t$https://www.hmdb.org/m.asp?m=145863$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Foster Community$t$, 29.64179::double precision, -95.82797::double precision, $t$Randolph Foster made a permanent camp here in the fall of 1821, on what became one of the largest single land grants in Texas, 11,601 acres in the name of his father John, one of Austin's "Old Three Hundred"; Foster family members fought in the Texas Revolution.$t$, $t$https://www.hmdb.org/m.asp?m=157742$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$LH7 Ranch$t$, 29.77608::double precision, -95.68579::double precision, $t$Emil Marks registered the LH7 brand in 1898 and built a Longhorn herd of 6,816 head on 36,000 acres; his yearly roundup barbecue grew into the LH7 Rodeo, which ended in 1950 when the Barker Reservoir flooded much of the ranch.$t$, $t$https://www.hmdb.org/m.asp?m=159176$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Barker Post Office$t$, 29.78272::double precision, -95.70161::double precision, $t$G.T. Miller opened Barker's post office in 1898 in a corner of his store, which was also a saloon; when the Postal Service thought about closing it in 1978, residents rallied and saved it.$t$, $t$https://www.hmdb.org/m.asp?m=159206$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$),
  ($t$Moore Log House$t$, 29.7715::double precision, -95.56983::double precision, $t$Edith L. Moore and her husband built this house in 1931–32 from pine logs cut on their own land, with a chimney of sandstone curbstones salvaged from downtown Houston; in 1975 she left it and 17.5 acres to the Houston Audubon Society as a nature sanctuary.$t$, $t$https://www.hmdb.org/m.asp?m=51060$t$, $t$#485 hidden-pin row — Katy-Energy Corridor part 1 (2026-10-28)$t$)
)
insert into public.curated_descriptions (name, lat, lng, description, source_url, note)
select v.name, v.lat, v.lng, v.description, v.source_url, v.note
from v
where not exists (
  select 1 from public.curated_descriptions d
  where d.name_clean = regexp_replace(lower(v.name), '[^a-z0-9]', '', 'g')
    and 6371000 * sqrt(
          power(radians(d.lat - v.lat), 2) +
          power(cos(radians((d.lat + v.lat) / 2)) * radians(d.lng - v.lng), 2)) <= 50
)
returning name, note;
